function toUtf8Bytes(str) {
  return Array.from(unescape(encodeURIComponent(str)), c => c.charCodeAt(0));
}
function hmacSha256Hex(keyStr, messageStr) {
  let key = toUtf8Bytes(keyStr);
  if (key.length > 64) key = sha256Bytes(key);
  while (key.length < 64) key.push(0);
  const oKey = key.map(b => b ^ 0x5c);
  const iKey = key.map(b => b ^ 0x36);
  const inner = sha256Bytes(iKey.concat(toUtf8Bytes(messageStr)));
  const outer = sha256Bytes(oKey.concat(inner));
  return outer.map(b => b.toString(16).padStart(2, '0')).join('');
}

const data = $input.first().json;
const shortId = String(data.patient_uuid).replace(/[^a-f0-9]/gi, '').slice(0, 6);
const isCritical = data.ai_triage.urgency_level === 'CRITICAL';

const callbackPayload = {
  patient_uuid: data.patient_uuid,
  status: isCritical ? 'EMERGENCY_HALTED' : 'CRM_SYNCED',
  ai_triage: data.ai_triage,
  hubspot_contact_id: `hs_cnt_${shortId}`,
  hubspot_deal_id: `hs_deal_${shortId}`
};

const rawBody = JSON.stringify(callbackPayload);
const timestamp = String(Math.floor(Date.now() / 1000));
const secret = 'aegis-dev-hmac-webhook-secret-key-2026';
const signature = hmacSha256Hex(secret, `${timestamp}.${rawBody}`);

return [{
  json: {
    callbackPayload,
    rawBody,
    signature,
    timestamp
  }
}];
